INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_122'), 1, 'For each event, which two facts about the job decide whether it may happen: the state it is in, and who is sending the event? Which events have a sender that must match, and which come from the system or an admin?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_122'), 2, 'Look at the order of the checks in the description: validation of the event itself first, then whether the job exists, then the state, then the owner, then the retry rules. A table from event type to the list of states it is allowed in replaces most of the if statements. And check that a rejected event returns before any field of the job is changed.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_122'), 3, 'A similar trace with maxAttempts 2 on an export job: enqueue x_1 -> queued. start(w1) -> running, attempts 1, owner w1. timeout -> failed, last failure retryable, owner cleared. heartbeat(w1) -> rejected: heartbeat is only allowed when running, and the job is failed. retry-scheduled -> retrying (attempts 1 < 2). start(w2) -> running, attempts 2, owner w2. fail(w1, retryable) -> rejected as a stale worker, because w1 is not the owner. fail(w2, retryable) -> failed. retry-scheduled -> rejected: attempts 2 is not below 2.');
