VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_122'), 'Grading job: a retryable failure, one retry, then success', '{"maxAttempts":3,"events":[{"type":"enqueue","jobId":"grade:s_1001"},{"type":"succeed","jobId":"grade:s_1001","workerId":"w1"},{"type":"start","jobId":"grade:s_1001","workerId":"w1"},{"type":"heartbeat","jobId":"grade:s_1001","workerId":"w1"},{"type":"fail","jobId":"grade:s_1001","workerId":"w1","failure":"retryable"},{"type":"retry-scheduled","jobId":"grade:s_1001"},{"type":"start","jobId":"grade:s_1001","workerId":"w2"},{"type":"succeed","jobId":"grade:s_1001","workerId":"w2"}]}', '"rejected #2 succeed grade:s_1001: succeed not allowed when queued\ngrade:s_1001 succeeded attempts=2"', 3, true, false, 1),
