-- lesson 1.3: Retries with exponential backoff & jitter (Sanity lesson-bjm-1-3)
UPDATE course.lesson SET title = 'Retries with exponential backoff & jitter', order_index = 3, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 1 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-1-3' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 1 AND is_deleted = false LIMIT 1), 'Retries with exponential backoff & jitter', 'sanity', 'lesson-bjm-1-3', 3
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-bjm-1-3' AND is_deleted = false);

-- challenge chal_quiz_bjm_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_131', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-1-3' AND is_deleted = false LIMIT 1), 'backoff-jitter-quiz', 'Reading a retry schedule', 'Two retry policies from CodeDev workers: an export queue whose retries arrive in waves, and a leaderboard job with exponential backoff and no cap.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_131'), 'Export worker policy:

const delay = 1000 * 2 ** (attempt - 1);   // attempt = the attempt that just failed

At 10:00:00.000 the storage service answered 503 to 1,000 export jobs that had started together. Storage access log, requests per millisecond bucket:

10:00:00.000   1,000 requests  (all 503)
10:00:01.000   1,000 requests  (all 503)
10:00:03.000   1,000 requests  (all 503)
10:00:07.000   1,000 requests  (987 x 503, 13 x 200)

Proposed change:

const delay = Math.floor(random() * 1000 * 2 ** (attempt - 1));   // full jitter

Statement: "With the proposed change, the 1,000 second attempts are spread between 10:00:00.000 and 10:00:00.999 instead of all starting at 10:00:01.000."', 'single_choice'::question_type, 'True. After the first failed attempt the backoff value is 1000 * 2^0 = 1,000 ms, and full jitter picks floor(random() * 1000), a whole number from 0 to 999 drawn independently for each job. The 1,000 retries therefore land spread across the first second after the failure, roughly one per millisecond, instead of as one burst at 10:00:01.000; the later waves are spread across 0-2 s, 0-4 s and so on. Some jobs retry sooner than before, which is intended: what the storage service feels is the number of requests arriving together, and that drops from 1,000 at one instant to about one at a time. The misconception is that jitter is a small random addition to make delays slightly longer; full jitter replaces the delay with a random value up to the backoff, so the average wait halves while the bursts disappear.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_131'), 'Leaderboard recompute job, retry options:

{
  attempts: 15,
  delayMs: (attempt) => Math.floor(random() * 1000 * 2 ** (attempt - 1)),   // full jitter, no cap
}

The job has failed 14 times in a row (the scores replica is being rebuilt). Attempt 15 will be its last.

Statement: "Because full jitter picks a random value, the wait before attempt 15 is about a minute on average."', 'single_choice'::question_type, 'False. The wait before attempt 15 is drawn after attempt 14 failed: the backoff value is 1000 * 2^13 = 8,192,000 ms, about 2 hours 16 minutes, and full jitter picks uniformly between 0 and that value, so the average wait is about 68 minutes and it can be over two hours. Jitter spreads delays between zero and the backoff value; it does not stop the backoff value itself from doubling with every attempt. That is what the cap is for: min(maxDelayMs, base * 2^(attempt - 1)) with a cap of, say, 60 s would keep every wait under a minute. For a leaderboard that is recomputed every few seconds anyway, 15 attempts is also far too many. The misconception is that randomness keeps delays small; without a cap the range grows exponentially and the random value grows with it.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_bjm_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_132', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-1-3' AND is_deleted = false LIMIT 1), 'retry-schedule-backoff-jitter', 'Retry schedule with backoff, jitter, Retry-After and a deadline', 'CodeDev workers (grading, certificate emails, exports, leaderboard) share one retry policy. Write planRetries(job, policy, random): walk job.attempts in order and return one entry per attempt that happened ({ attempt, startAt, endAt, outcome, delayMs?, retryAt? }). Attempt 1 starts at job.firstAttemptAt; attempt n ends at endAt = startAt + durationMs. After attempt n: 1. error is null -> outcome "succeeded", stop. 2. error.retryable is false -> "permanent", stop. 3. n >= policy.maxAttempts -> "max-attempts", stop. 4. otherwise call random() exactly once: capped = min(maxDelayMs, baseDelayMs * 2^(n - 1)); delayMs = floor(random() * capped) (full jitter); if error.retryAfterMs is present and larger than delayMs, delayMs = error.retryAfterMs; retryAt = endAt + delayMs. If retryAt > job.firstAttemptAt + policy.deadlineMs -> outcome "deadline" with delayMs and retryAt, stop. Otherwise outcome "retry" with delayMs and retryAt, and attempt n + 1 starts at retryAt; if job.attempts has no entry for it, stop after the "retry" entry. Never call random() for a success, a permanent error or the last allowed attempt: the runner shares one random sequence across all jobs of a test, in order. Throw new Error("invalid policy") when baseDelayMs <= 0, maxDelayMs < baseDelayMs, maxAttempts is not a whole number >= 1, or deadlineMs <= 0. Input (JSON on stdin): { policy, random: number[] (each in [0, 1), cycling), jobs: [{ name, firstAttemptAt, attempts: [{ durationMs, error: null | { retryable, retryAfterMs? } }] }] }. The runner prints one line per entry ("<name> #<attempt> <startAt>-<endAt> <outcome>", plus " delay=<delayMs> at=<retryAt>" when present), "<name> error: <message>" when planRetries throws, and finally "random calls <n>". Up to 250 jobs per test; all times are whole milliseconds on a fake clock.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 1, 'After a failed attempt, which questions can you answer without any randomness (did it succeed, can it ever succeed, is this the last allowed attempt), and which one needs the random number? Ask them in that order and the number of random() calls takes care of itself.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 2, 'Look at three places: where the cap is applied (before the random number multiplies it, not after), the comparison with Retry-After (it only wins when it is larger), and the deadline, which is measured from job.firstAttemptAt, not from the failure, with retryAt equal to the deadline still allowed. Remember that attempt n + 1 starts at the retryAt of attempt n.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 3, 'A similar schedule with base 200, cap 1,000, maxAttempts 5, deadline 3,000, random values 0.5, 0.9, 0.25 and a job that starts at 100 and fails after 50 ms each time: attempt 1 ends at 150, capped 200, delay 100, retry at 250. Attempt 2 ends at 300, capped 400, delay 360, retry at 660. Attempt 3 fails with retryAfterMs 2,000 and ends at 710: capped 800, jitter 200, Retry-After is larger, so the delay is 2,000 and the retry would be at 2,710, which is not after 3,100, so it is scheduled. A Retry-After of 50 there would have kept the delay at 200.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
