       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 'Certificate email: Retry-After wins only when larger; a permanent error draws no random', '{"policy":{"baseDelayMs":2000,"maxDelayMs":60000,"maxAttempts":4,"deadlineMs":600000},"random":[0.9,0.1,0.5],"jobs":[{"name":"email:cert_77","firstAttemptAt":1000,"attempts":[{"durationMs":200,"error":{"retryable":true,"retryAfterMs":30000}},{"durationMs":150,"error":{"retryable":true,"retryAfterMs":100}},{"durationMs":300,"error":{"retryable":true}},{"durationMs":250,"error":{"retryable":true}}]},{"name":"export:c_12","firstAttemptAt":5000,"attempts":[{"durationMs":40,"error":{"retryable":false}},{"durationMs":10,"error":null}]},{"name":"email:cert_78","firstAttemptAt":9000,"attempts":[{"durationMs":100,"error":{"retryable":true}},{"durationMs":100,"error":null}]}]}', '"email:cert_77 #1 1000-1200 retry delay=30000 at=31200\nemail:cert_77 #2 31200-31350 retry delay=400 at=31750\nemail:cert_77 #3 31750-32050 retry delay=4000 at=36050\nemail:cert_77 #4 36050-36300 max-attempts\nexport:c_12 #1 5000-5040 permanent\nemail:cert_78 #1 9000-9100 retry delay=1800 at=10900\nemail:cert_78 #2 10900-11000 succeeded\nrandom calls 4"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 'Cap: once base x 2^(n-1) passes maxDelayMs, every delay is drawn from maxDelayMs', '{"policy":{"baseDelayMs":500,"maxDelayMs":10000,"maxAttempts":10,"deadlineMs":10000000},"random":[0.999999,0.5],"jobs":[{"name":"leaderboard:recompute","firstAttemptAt":100,"attempts":[{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":{"retryable":true}},{"durationMs":1000,"error":null}]}]}', '"leaderboard:recompute #1 100-1100 retry delay=499 at=1599\nleaderboard:recompute #2 1599-2599 retry delay=500 at=3099\nleaderboard:recompute #3 3099-4099 retry delay=1999 at=6098\nleaderboard:recompute #4 6098-7098 retry delay=2000 at=9098\nleaderboard:recompute #5 9098-10098 retry delay=7999 at=18097\nleaderboard:recompute #6 18097-19097 retry delay=5000 at=24097\nleaderboard:recompute #7 24097-25097 retry delay=9999 at=35096\nleaderboard:recompute #8 35096-36096 retry delay=5000 at=41096\nleaderboard:recompute #9 41096-42096 retry delay=9999 at=52095\nleaderboard:recompute #10 52095-53095 succeeded\nrandom calls 9"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 'Deadline: a retry exactly at the deadline is scheduled, one past it is not', '{"policy":{"baseDelayMs":1000,"maxDelayMs":8000,"maxAttempts":6,"deadlineMs":10000},"random":[0,0.75,0.6],"jobs":[{"name":"grade:s_1","firstAttemptAt":5000,"attempts":[{"durationMs":4000,"error":{"retryable":true,"retryAfterMs":6000}},{"durationMs":100,"error":{"retryable":true}},{"durationMs":50,"error":null}]},{"name":"email:cert_2","firstAttemptAt":20000,"attempts":[{"durationMs":300,"error":{"retryable":true,"retryAfterMs":3600000}},{"durationMs":10,"error":null}]},{"name":"export:c_3","firstAttemptAt":40000,"attempts":[{"durationMs":2000,"error":{"retryable":true}},{"durationMs":3000,"error":{"retryable":true}},{"durationMs":3000,"error":{"retryable":true}},{"durationMs":5,"error":null}]}]}', '"grade:s_1 #1 5000-9000 retry delay=6000 at=15000\ngrade:s_1 #2 15000-15100 deadline delay=1500 at=16600\nemail:cert_2 #1 20000-20300 deadline delay=3600000 at=3620300\nexport:c_3 #1 40000-42000 retry delay=0 at=42000\nexport:c_3 #2 42000-45000 retry delay=1500 at=46500\nexport:c_3 #3 46500-49500 deadline delay=2400 at=51900\nrandom calls 6"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_132'), 'Invalid policy: maxDelayMs smaller than baseDelayMs is rejected for every job', '{"policy":{"baseDelayMs":1000,"maxDelayMs":500,"maxAttempts":3,"deadlineMs":60000},"random":[0.5],"jobs":[{"name":"grade:s_5","firstAttemptAt":0,"attempts":[{"durationMs":10,"error":{"retryable":true}},{"durationMs":10,"error":null}]},{"name":"email:cert_6","firstAttemptAt":0,"attempts":[{"durationMs":10,"error":null}]}]}', '"grade:s_5 error: invalid policy\nemail:cert_6 error: invalid policy\nrandom calls 0"', 2, false, true, 5),
