-- module 2: Delivery
UPDATE course.module SET title = 'Delivery', updated_at = now() WHERE id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 2 AND is_deleted = false LIMIT 1);
