SELECT (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), 'Delivery', 2
WHERE NOT EXISTS (SELECT 1 FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 2 AND is_deleted = false);

