INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_212', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-2-1' AND is_deleted = false LIMIT 1), 'idempotent-certificate-worker', 'Issue each certificate once', 'The CodeDev certificates worker receives issue-certificate jobs { id, data: { userId, courseId } } from a queue that delivers at least once: a delivery that is not acknowledged comes back after the visibility timeout, and the same completion can also be enqueued twice under two job ids. Today the worker inserts a certificate and publishes a certificate.issued event on every delivery, so a worker that crashes before its ack issues the certificate twice. Rewrite handleIssueCertificate(job, db) to be idempotent. The idempotency key is the business key "certificate:<userId>:<courseId>". Inside one db.transaction(tx => ...): if tx.hasProcessed(key), write nothing and return "duplicate"; otherwise insert the certificate (tx.insertCertificate({ userId, courseId, jobId: job.id })), publish the event (tx.publishEvent({ type: "certificate.issued", userId, courseId })) and mark the key processed (tx.markProcessed(key)), then return "issued". A crash inside a transaction rolls back all of its writes; the same calls made on db directly commit one by one. A job whose userId or courseId is missing, not a string, or blank returns "invalid" and writes nothing. Do not catch errors. Input (read by the runner): { visibilityTimeoutMs, jobs: [{ id, data, at? }], crashes?: [{ job, delivery, point }] } where point "after_side_effect" crashes the worker right after the first certificate or event write of that delivery and "before_ack" crashes it after your function returned. Output: one JSON object { log, certificates, events }: one log line per delivery ("t=<ms> <jobId> #<delivery>: <outcome>"), and every committed certificate and event in order.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
