-- challenge chal_quiz_bjm_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_221', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-2-2' AND is_deleted = false LIMIT 1), 'visibility-timeout-quiz', 'Why did the grading job run twice?', 'Two pieces of evidence from the grading queue: the worker logs of the duplicated submission, and a heartbeat added to a worker that grades in its own process.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_221'), 'Queue attribute: VisibilityTimeout = 60 (seconds). Worker logs:

12:00:00.012 grader-1 received sub_4471 receiveCount=1
12:01:00.031 grader-2 received sub_4471 receiveCount=2
12:01:10.144 grader-1 graded sub_4471 in 70.1 s -> result r_9001
12:01:10.162 grader-1 DeleteMessage sub_4471 (receipt from 12:00:00) -> 200
12:02:10.377 grader-2 graded sub_4471 in 70.3 s -> result r_9002
12:02:10.391 grader-2 DeleteMessage sub_4471 (receipt from 12:01:00) -> 200

The graders do not call ChangeMessageVisibility.

Statement: "The delivery to grader-2 at 12:01:00 is the queue working as configured: grader-1 had neither deleted the message nor extended its visibility within 60 seconds of receiving it."', 'single_choice'::question_type, 'True. Receiving a message hides it for the visibility timeout; it is not handed over for good. Grader-1 received it at 12:00:00 and its delete only came at 12:01:10, after the 60-second lease had ended, and it never extended the lease. At 12:01:00 the message was visible again, so the next receive delivered it with a receive count of 2 and a new receipt handle. The queue cannot tell a slow worker from a dead one. The fix is on the configuration and worker side: a timeout above the measured p99 of the jobs, a heartbeat that extends the lease while the work is alive, and an idempotent result write. The misconception is that a redelivery is a queue bug; it is the mechanism that recovers jobs from crashed workers.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_221'), 'A team grades small Python submissions inside the worker process itself and adds a heartbeat:

const heartbeat = setInterval(() => {
  sqs.send(new ChangeMessageVisibilityCommand({ QueueUrl, ReceiptHandle: msg.ReceiptHandle, VisibilityTimeout: 60 }))
    .then(() => logger.info("heartbeat", msg.MessageId));
}, 20_000);
try {
  const result = runTestsSync(submission);   // synchronous, CPU-bound, up to 70 s
  await saveResult(result);
  await deleteMessage(msg);
} finally {
  clearInterval(heartbeat);
}

Logs for a 70-second run: "received" at 0 s, "graded" at 70 s, no "heartbeat" line in between.

Statement: "Because the worker calls ChangeMessageVisibility every 20 seconds, a 70-second run can no longer be received by a second worker."', 'single_choice'::question_type, 'False. setInterval callbacks run on the event loop, and runTestsSync keeps the event loop busy for the whole 70 seconds, so the timer cannot fire until the tests are done: the missing "heartbeat" lines prove it. The lease is never extended, ends at 60 seconds, and a second worker can receive the message, exactly as before. BullMQ''s automatic lock renewal fails the same way, which shows up as stalled jobs. CPU-bound work has to run outside the event loop (a worker thread, a child process, a sandboxed processor or a separate service) for a heartbeat to work. The misconception is that scheduling a timer guarantees it runs on time; in Node.js it runs only when the event loop is free.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_bjm_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_222', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-2-2' AND is_deleted = false LIMIT 1), 'visibility-timeout-queue', 'Build the lease: receive, ack, extend and redeliver', 'CodeDev''s grading queue ran a 70-second job twice because its visibility timeout is 60 seconds, and an old delivery''s ack could act on a message that a newer delivery was grading. Implement the queue side, class VisibilityQueue(visibilityTimeoutMs), on a fake clock (every method gets `now` in milliseconds). send(id, body, now): the message is visible from now; ids are unique. receive(now): among messages visible at or before now, take the one that became visible earliest (ties: sent first), add 1 to its receive count, issue the receipt handle "<id>#<receiveCount>", hide it until now + visibilityTimeoutMs and return { messageId, body, receiptHandle, receiveCount }; return null when none is visible. ack(receiptHandle, now): delete the message and return true only if the handle is current, meaning it is the latest handle issued for a message that still exists (it stays valid after the timeout passed, until the message is received again); otherwise return false and change nothing. extendVisibility(receiptHandle, timeoutMs, now): only for a current handle whose message is still hidden (now < the time it becomes visible), hide it until now + timeoutMs and return true; timeoutMs 0 makes it visible at once. Return false and change nothing if the handle is not current, the message is visible again, or timeoutMs is not a whole number from 0 to 43200000. The runner simulates workers that poll, work for each message''s workMs, send heartbeats, crash, and make extra client calls. Input: { visibilityTimeoutMs, untilMs, messages: [{ id, at, workMs }], workers: [{ name, pollMs, heartbeatMs?, extendMs? }], crashes?: [{ message, delivery, afterMs }], calls?: [{ at, ack? | extend?, timeoutMs? }] }. Output: { deliveries (receives per message), rejectedAcks, remaining (not deleted), log }.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
