INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 1, 'For each stored message, what must the queue remember so that it can answer two questions at any time: is it visible at `now`, and which receipt handle is allowed to act on it?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 2, 'Look at what receive changes (receive count, current handle, the time the message becomes visible), and make ack and extendVisibility start with the same check: find the message from the handle and compare the handle with the latest one issued. extendVisibility has two more conditions: the message is still hidden, and timeoutMs is valid.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 3, 'A worked trace with a 30,000 ms timeout: send m at 0. receive(0) gives m#1, hidden until 30,000. extendVisibility("m#1", 30000, 20000) is true: hidden until 50,000. receive(49999) is null; receive(50000) gives m#2. Now ack("m#1", 51000) is false, extendVisibility("m#1", 1000, 51000) is false, and ack("m#2", 90000) is true even though m#2''s lease ended at 80,000, because nobody received m again.');
