VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 'The incident: a 70 s job with a 60 s timeout is received again every 60 s and every ack is rejected', '{"visibilityTimeoutMs":60000,"untilMs":200000,"messages":[{"id":"grade-s1","at":0,"workMs":70000}],"workers":[{"name":"w1","pollMs":5000},{"name":"w2","pollMs":5000}]}', '{"deliveries":{"grade-s1":4},"rejectedAcks":["t=70000 w1 grade-s1#1","t=130000 w2 grade-s1#2","t=190000 w1 grade-s1#3"],"remaining":["grade-s1"],"log":["t=0 w1 received grade-s1#1 (receive count 1)","t=60000 w2 received grade-s1#2 (receive count 2)","t=70000 w1 ack grade-s1#1 rejected","t=120000 w1 received grade-s1#3 (receive count 3)","t=130000 w2 ack grade-s1#2 rejected","t=180000 w2 received grade-s1#4 (receive count 4)","t=190000 w1 ack grade-s1#3 rejected"]}', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 'Short jobs are received once each and deleted by their ack', '{"visibilityTimeoutMs":30000,"untilMs":60000,"messages":[{"id":"grade-a","at":0,"workMs":10000},{"id":"grade-b","at":0,"workMs":10000},{"id":"grade-c","at":2000,"workMs":10000}],"workers":[{"name":"w1","pollMs":1000}]}', '{"deliveries":{"grade-a":1,"grade-b":1,"grade-c":1},"rejectedAcks":[],"remaining":[],"log":["t=0 w1 received grade-a#1 (receive count 1)","t=10000 w1 ack grade-a#1 ok","t=10000 w1 received grade-b#1 (receive count 1)","t=20000 w1 ack grade-b#1 ok","t=20000 w1 received grade-c#1 (receive count 1)","t=30000 w1 ack grade-c#1 ok"]}', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 'Heartbeat every 20 s keeps the 70 s job with one worker', '{"visibilityTimeoutMs":60000,"untilMs":200000,"messages":[{"id":"grade-s1","at":0,"workMs":70000}],"workers":[{"name":"w1","pollMs":5000,"heartbeatMs":20000,"extendMs":60000},{"name":"w2","pollMs":5000,"heartbeatMs":20000,"extendMs":60000}]}', '{"deliveries":{"grade-s1":1},"rejectedAcks":[],"remaining":[],"log":["t=0 w1 received grade-s1#1 (receive count 1)","t=70000 w1 ack grade-s1#1 ok"]}', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 'A crashed worker''s message returns when its last extension ends, with receive count 2', '{"visibilityTimeoutMs":30000,"untilMs":200000,"messages":[{"id":"grade-s2","at":0,"workMs":90000}],"workers":[{"name":"w1","pollMs":5000,"heartbeatMs":20000,"extendMs":30000},{"name":"w2","pollMs":5000,"heartbeatMs":20000,"extendMs":30000}],"crashes":[{"message":"grade-s2","delivery":1,"afterMs":50000}]}', '{"deliveries":{"grade-s2":2},"rejectedAcks":[],"remaining":[],"log":["t=0 w1 received grade-s2#1 (receive count 1)","t=50000 w1 crashed working on grade-s2#1","t=70000 w1 received grade-s2#2 (receive count 2)","t=160000 w1 ack grade-s2#2 ok"]}', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 'A late ack with the current handle is accepted; extending an expired message is rejected', '{"visibilityTimeoutMs":30000,"untilMs":200000,"messages":[{"id":"grade-m1","at":0,"workMs":45000},{"id":"grade-m2","at":1000,"workMs":20000}],"workers":[{"name":"w1","pollMs":100000}],"crashes":[{"message":"grade-m2","delivery":1,"afterMs":1000}],"calls":[{"at":80000,"extend":"grade-m2#1","timeoutMs":10000},{"at":90000,"ack":"grade-m2#1"}]}', '{"deliveries":{"grade-m1":1,"grade-m2":1},"rejectedAcks":[],"remaining":[],"log":["t=0 w1 received grade-m1#1 (receive count 1)","t=45000 w1 ack grade-m1#1 ok","t=45000 w1 received grade-m2#1 (receive count 1)","t=46000 w1 crashed working on grade-m2#1","t=80000 client extend grade-m2#1 10000 rejected","t=90000 client ack grade-m2#1 ok"]}', 2, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_222'), 'Invalid handles and timeouts are rejected; extend 0 releases the message', '{"visibilityTimeoutMs":30000,"untilMs":60000,"messages":[{"id":"grade-a","at":0,"workMs":20000}],"workers":[{"name":"w1","pollMs":1000},{"name":"w2","pollMs":1000}],"calls":[{"at":5000,"ack":""},{"at":5000,"ack":"grade-a"},{"at":5000,"ack":"grade-x#1"},{"at":5000,"ack":"grade-a#0"},{"at":5000,"ack":"grade-a#2"},{"at":6000,"extend":"grade-a#1","timeoutMs":-1},{"at":6000,"extend":"grade-a#1","timeoutMs":1.5},{"at":6000,"extend":"grade-a#1","timeoutMs":50000000},{"at":6000,"extend":"nope#1","timeoutMs":1000},{"at":7000,"extend":"grade-a#1","timeoutMs":0}]}', '{"deliveries":{"grade-a":2},"rejectedAcks":["t=20000 w1 grade-a#1"],"remaining":[],"log":["t=0 w1 received grade-a#1 (receive count 1)","t=5000 client ack  rejected","t=5000 client ack grade-a rejected","t=5000 client ack grade-x#1 rejected","t=5000 client ack grade-a#0 rejected","t=5000 client ack grade-a#2 rejected","t=6000 client extend grade-a#1 -1 rejected","t=6000 client extend grade-a#1 1.5 rejected","t=6000 client extend grade-a#1 50000000 rejected","t=6000 client extend nope#1 1000 rejected","t=7000 client extend grade-a#1 0 ok","t=7000 w2 received grade-a#2 (receive count 2)","t=20000 w1 ack grade-a#1 rejected","t=27000 w2 ack grade-a#2 ok"]}', 2, false, true, 6),
