-- challenge chal_quiz_bjm_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_231', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-2-3' AND is_deleted = false LIMIT 1), 'retry-everything-quiz', 'Which export failures are worth a retry?', 'Two pieces of evidence from the export worker: the log of an export retried ten times, and a first attempt at classifying errors.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_231'), 'Export worker log (10 attempts, exponential backoff from 1 s, capped at 30 s):

14:03:02.118 exp-7731 attempt=1 HttpError: reports API answered 404 (course "nestjs-basics")
14:03:03.121 exp-7731 attempt=2 HttpError: reports API answered 404 (course "nestjs-basics")
14:03:05.125 exp-7731 attempt=3 HttpError: reports API answered 404 (course "nestjs-basics")
   ... attempts 4 to 9: the same 404 ...
14:05:33.161 exp-7731 attempt=10 HttpError: reports API answered 404 (course "nestjs-basics")
14:05:33.163 exp-7731 ALERT export exp-7731 failed

The course nestjs-basics was renamed months ago; GET /courses/nestjs-basics/progress answers 404 every time.

Statement: "None of the nine retries could have succeeded, and the alert came about two and a half minutes later than it could have."', 'single_choice'::question_type, 'True. A 404 for a course that does not exist describes the request, not a temporary state of the reports API: sending the same request again gets the same answer, so every retry was wasted work and the worker was blocked for 151 seconds (1 + 2 + 4 + 8 + 16 + 30 x 4 seconds of sleeping). The alert could have been sent after the first attempt at 14:03:02 instead of at 14:05:33. A 404 is a permanent error: fail the export at once with the reason and alert. The misconception is that more attempts always make a worker more reliable; for permanent errors they only add load and delay the moment someone finds out.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_231'), 'A reviewer''s first fix of the export worker:

} catch (error) {
  lastError = error;
  const clientError = error instanceof HttpError && error.status >= 400 && error.status < 500;
  if (attempt === MAX_ATTEMPTS || clientError) break;   // 4xx: our request is wrong, stop
  // ... sleep with backoff or Retry-After, then retry
}

At 17:00, when many instructors export at once, the reports API answers:

HTTP/1.1 429 Too Many Requests
Retry-After: 5

Statement: "With this change, the export that got 429 is failed for good, and that is the right outcome for a request the reports API rejected."', 'single_choice'::question_type, 'False. The first half is accurate - the code treats 429 like any other 4xx and stops - but that outcome is wrong. 429 does not say the request is invalid; it says the client is sending too many requests right now, and Retry-After: 5 says when to try again. The same request will very likely succeed after five seconds, so it is retryable, and so is 408 Request Timeout. The correct rule is 4xx except 408 and 429 is permanent; 5xx, timeouts and connection resets are retryable. The misconception is that the status class alone decides; the meaning of the specific code does.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_231') AND order_index = 2)
    RETURNING id
)
