SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_bjm_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_232', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-2-3' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-retry-everything', 'Spot the AI Mistake: retrying errors that can never succeed', 'An AI assistant was asked: "The course export worker fails now and then and instructors have to click Export again. Make the export worker reliable." It wrapped the export in runExportJob: up to 10 attempts with exponential backoff (1 s doubling, capped at 30 s) that honours Retry-After, then an alert. Its tests, with a reports API that times out or answers 503 or 429 and then recovers, passed. In production the export queue falls behind and alerts arrive minutes late: an export with a malformed course id, a 404 or 403 from the reports API, or a missing template file is attempted 10 times over 151 seconds before the alert. Fix runExportJob so that only errors that can go away on their own are retried: TimeoutError, a connection reset (code "ECONNRESET"), HttpError 5xx, 408 and 429 (waiting retryAfterMs when set). ValidationError, HttpError 4xx other than 408 and 429, and a missing file (code "ENOENT") are permanent: fail the job at once, without sleeping and without another attempt, and alert immediately. Keep the limit, the backoff, the alert and the result as they are. Input: a list of export jobs { id, courseId, format, script }, where script lists what each attempt meets ("ok", "reports:timeout", "reports:reset", "reports:<status>[:<retryAfterSeconds>]", "template:missing", "storage:timeout", "storage:<status>"; the last entry repeats). Output: one line per job with its status, attempts, fake worker time and alert time, then a total line. The public tests pass on the assistant''s code; the hidden tests use failures that never recover.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_232');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_232'), 1, 'Inside the catch block, before deciding to sleep, what question about the error should the worker ask, and what does it do today with an error whose answer can never change?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_232'), 2, 'Look at the line that decides whether the loop ends early, and at the information each error carries: its class (ValidationError, TimeoutError, HttpError), the status of an HttpError, and the code of a system error. The decision has to happen before the sleep, or a permanent error still costs one backoff delay.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_232'), 3, 'A similar decision for an SMTP mailer, where the rule is reversed: reply codes 4xx are temporary and 5xx are permanent. With attempts that meet 451, then 451, then 250, the mail is sent on attempt 3 after two backoff delays; with 550 on the first attempt, the job fails on attempt 1 with no delay and the alert goes out at once. Write the rule as one small function that takes the error and returns whether the same request could succeed later.');
