-- challenge chal_coding_bjm_312 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_312', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-3-1' AND is_deleted = false LIMIT 1), 'poison-message-growing-queue', 'Poison Message & Growing Queue', 'Since 09:02 the CodeDev grade-submissions queue has grown from 200 to 80,000 waiting submissions. The logs show the same job failing with a parser error every 30 seconds and going back to the head of the queue; nothing behind it is graded. The queue is FIFO with concurrency 1: workOnce(worker, now) is called once per second and may only attempt the message at the head; while the head waits for its retry (notBefore > now) nothing behind it may start. Fix workOnce so it follows the team''s new retry policy: at most 3 attempts per message in total, whatever the error; after a failed attempt that is not the 3rd, the message stays at the head and is retried 30 s later; when the 3rd attempt fails, the message leaves the queue and is added to the dead-letter list with its id, its attempt count, its last error message and the current second, and the next message can be attempted from the next second on. A message that succeeds on any attempt is graded normally. Input (one JSON object on stdin): { until, sampleEvery, messages: [{ id, at, body }] }; each second from 0 to until, messages arriving at that second join the tail, then workOnce runs once. Output (printed by the runner): the graded submissions in order as "id@second", the dead-letter list as "id after N attempts at T: error", the queue depth sampled every sampleEvery seconds, and the message left at the head. Do not change the grader or the test runner.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
