INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_312'), 1, 'The starter retries every failure, forever, at the head. What should happen differently on the 3rd failed attempt of the same message, and which list should it end up in?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_312'), 2, 'Look at the catch block of workOnce and at MAX_ATTEMPTS. head.attempts already counts the attempt that just failed. Only one branch should keep the message at the head; the other must remove it from the queue so the next message becomes the head.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_312'), 3, 'A similar case with a limit of 2 attempts and a 10 s delay: a message fails at second 4 (attempt 1) and at second 14 (attempt 2). Attempt 2 is the last one, so at second 14 the message is parked with "after 2 attempts at 14" and its error, and the message behind it is attempted at second 15.');
