-- challenge chal_quiz_bjm_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_321', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-3-2' AND is_deleted = false LIMIT 1), 'dead-letter-queue-redrive', 'Dead-letter queues & redrive: choose what to replay', 'The certificate renderer dead-lettered 1,189 messages this week. A fix for the biggest group is deployed. Two statements on the DLQ listing decide what to redrive, and how fast.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_321'), '$ codedev-queue dlq list certificate-renderer-dlq --group-by lastError
lastError                                           count  schema  first failure     last failure
RenderError: font "Inter Display" not found         1,184  v2      10-27 08:12       10-27 09:40
SchemaVersionError: unsupported payload version 1       3  v1      10-21 14:03       10-21 14:05
ValidationError: course c_404 does not exist            2  v2      10-25 10:31       10-25 10:33

10-27 09:52 deploy certificate-renderer 1.14.2 "bundle the Inter Display font"
main queue certificate-renderer: 35 waiting, about 40 new messages per minute, renderer capacity about 120 per minute

Plan: redrive only the 1,184 RenderError entries, at 50 messages per minute, and leave the other 5 entries in the DLQ with a ticket for the course team.

Statement: "This plan is a safe redrive: the fix for the RenderError group is deployed, the rate leaves room for new certificates, and the other two groups would fail again or be misread by the current code."', 'single_choice'::question_type, 'True. Redrive replays messages through the current code, so it only makes sense for a group whose cause has been fixed: the 09:52 deploy fixes the missing font, the cause of the RenderError group. 50 per minute on top of about 40 new messages stays under the renderer''s 120 per minute, so new certificates are not delayed while the backlog of 1,184 drains in about 24 minutes. The SchemaVersionError group carries v1 payloads the current code does not support, and the ValidationError group points at a course that does not exist: replaying them changes nothing or, worse, produces wrong certificates. Grouping by last error is what turns a DLQ from a pile into a set of decisions.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_321'), '$ codedev-queue dlq list certificate-renderer-dlq --group-by lastError
lastError                                           count  schema  first failure     last failure
RenderError: font "Inter Display" not found         1,184  v2      10-27 08:12       10-27 09:40
SchemaVersionError: unsupported payload version 1       3  v1      10-21 14:03       10-21 14:05
ValidationError: course c_404 does not exist            2  v2      10-25 10:31       10-25 10:33

10-27 09:52 deploy certificate-renderer 1.14.2 "bundle the Inter Display font"
main queue certificate-renderer: 35 waiting, about 40 new messages per minute, renderer capacity about 120 per minute

Statement: "Redriving all 1,189 entries at once is just as safe: anything that still fails simply goes back to the DLQ, so nothing can go wrong."', 'single_choice'::question_type, 'False. Three things go wrong. 1,189 messages arrive at a renderer that handles about 120 a minute, so for about ten minutes new certificates wait behind the replay. The 2 ValidationError messages can never succeed and use up three attempts each for nothing, and the 3 v1 messages reach code that does not support their schema: depending on the code they fail again or, worse, are read with the wrong field names and render a wrong certificate - a quiet failure no DLQ catches. A safe redrive selects by cause (last error) after the fix, refuses schemas the code cannot read, is rate-limited, and never adds a message that is already back in the main queue.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_bjm_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_322', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-3-2' AND is_deleted = false LIMIT 1), 'dead-letter-queue-redrive', 'Dead-letter queue with redrive and purge', 'The certificate-renderer queue of CodeDev needs a dead-letter queue (DLQ) that on-call engineers can work with. Implement tick, redrive and purge on an in-memory queue with a fake clock in minutes. The runner reads { config: { maxAttempts, redrivePerTick, supportedSchemas }, commands } and applies the commands in order: send (append to the main queue, attempts 0), tick { minutes? = 1 } (calls tick once per minute), redrive { ids } or { error }, deploy { fix } (from then on, messages failing with that error succeed) and purge { olderThanDays }; after each command it prints the events you return and the main queue, DLQ and redrive list. tick(state): 1) add 1 to state.now; 2) redrive, rate-limited: take up to redrivePerTick ids from the front of state.redrivePending (each taken id counts, moved or not); if a message with the same id is in the main queue, leave the DLQ entry where it is and emit "<id>: already in the main queue, left in the DLQ"; otherwise remove it from the DLQ, append it to the tail of the main queue with attempts 0 and the failure fields null, and emit "redriven <id>"; 3) deliver once: if the main queue is not empty, take the head, add 1 to its attempts and call handle(state, msg); on success emit "processed <id>"; on error set firstFailedAt (only if null) and lastFailedAt to now and lastError to the error message, then if attempts >= maxAttempts append it to the DLQ with id, schema, body, attempts, firstFailedAt, lastFailedAt, lastError and emit "dead-lettered <id> after <n> attempts: <error>", else append it to the tail of the main queue and emit "failed <id> attempt <n>: <error>". redrive(state, cmd): give exactly one of a non-empty ids array or a non-empty error string, else return ["rejected: give either ids or error"]; ids are used in the given order; an error selects the DLQ entries whose lastError equals it, in DLQ order, and if none match return ["no dead letters with error <error>"]. For each selected id, in this order of checks: not in the DLQ: "<id>: not in the DLQ"; schema not in supportedSchemas: "<id>: schema v<schema> is not supported, not redriven"; already in redrivePending: "<id>: already queued for redrive"; otherwise append it to redrivePending: "<id>: queued for redrive". purge(state, olderThanDays): unless it is a whole number of at least 1, return ["rejected: olderThanDays must be a whole number of at least 1"] and delete nothing; otherwise delete every DLQ entry with now - lastFailedAt >= olderThanDays * 1440, also remove its id from redrivePending, and emit "purged <id>" for each, in DLQ order. Ids are unique within the DLQ. Do not change the handler or the test runner.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
