INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_322'), 1, 'Write down, for one message, the full life you expect: sent, failed twice, dead-lettered, queued for redrive, moved back, processed. Which fields must change at each step, and which step is the only one allowed to move it from the DLQ to the main queue?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_322'), 2, 'In tick, the order matters: the clock first, then at most redrivePerTick ids from the front of redrivePending (splice is handy), then exactly one delivery. In redrive, the three refusal checks come before anything is added to redrivePending. In purge, validate the argument before you filter.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_322'), 3, 'A similar case with maxAttempts 2 and redrivePerTick 1: x fails at minutes 1 and 2 and is dead-lettered with first=1 last=2. After a deploy, redrive ids [x, y] gives "x: queued for redrive" and "y: not in the DLQ". At minute 3 x is moved back with attempts 0 and processed in the same minute. A purge with 0 days at that point deletes nothing.');
