INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_331', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-3-3' AND is_deleted = false LIMIT 1), 'duplicate-side-effects', 'Certificate emails sent twice: what stops the duplicate', 'A learner received the same certificate email twice after a worker was stopped between sending the email and writing "sent". Two statements on the worker code and its logs ask which change actually prevents the second email.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
