WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_331'), '// apps/worker/src/certificates/certificate-email.processor.ts
async process(job: Job<{ certId: string }>) {
  const cert = await this.certificates.findById(job.data.certId);
  if (!cert || cert.emailStatus !== "pending") return;
  await this.mailer.send({ to: cert.email, template: "certificate-issued", data: { certId: cert.id } });
  await this.certificates.setEmailStatus(cert.id, "sent");
}

