-- challenge chal_coding_bjm_332 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_332', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-3-3' AND is_deleted = false LIMIT 1), 'certificate-emails-sent-twice', 'Certificate emails sent twice', 'Since the CodeDev workers moved to spot instances, some learners get their certificate email two or three times. The queue delivers at least once: a worker that dies after sending the email but before writing "sent" leaves the job to be delivered again, and a worker slower than the visibility timeout sees a second worker pick up the same job while it is still running. Fix sendCertificateEmail(job, ctx) so each certificate email is delivered once, following this protocol. key = "certificate-email/<certId>", the same for every delivery of that certificate. 1) Read the certificate with ctx.db.get; if it is unknown (null), "sent" or "needs-review", do nothing. 2) If it is "pending", claim it with ctx.db.update(id, "pending", { status: "sending", claimedAt: ctx.now() }); update is a compare-and-set that returns false when the status is no longer "pending" - in either case read the certificate again and continue from step 1 with the new status. 3) If it is "sending" and ctx.now() - claimedAt < 86400 (24 h), send it with ctx.email.send({ to, template: "certificate-issued", certId, idempotencyKey: key }), then ctx.db.update(id, "sending", { status: "sent" }) (a false result is fine: another worker finished first). 4) If it is "sending" and ctx.now() - claimedAt >= 86400, do not send - the provider no longer remembers the key, so a resend could reach the learner twice; set ctx.db.update(id, "sending", { status: "needs-review" }) for a person to check the provider''s log. The email provider fake delivers at most once per idempotencyKey within 24 h (a send whose key was delivered less than 86,400 s earlier returns "duplicate" and delivers nothing; without a key it always delivers). Input: { certificates, script }; the script plays the broker: { at, deliver, cert, crashAfter?, pauseAfter? } starts a worker on a delivery, { at, resume } lets a paused worker continue; crashAfter/pauseAfter name an operation ("get", "update", "send") after whose first call, once it has taken effect, the worker dies (never continues) or pauses. Output: emails delivered per learner, the final status of every certificate, and worker errors. Do not change the fakes or the test runner.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
