INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_332'), 1, 'List every point where the worker can stop: after reading, after sending, after writing. For each one, what does the next delivery of the same job find in the database, and what does it do? Which of those points produces a second email today?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_332'), 2, 'Two things must change in sendCertificateEmail: the database must say "someone has started this" before the email is sent (the claim, with the time), and the email must carry a key that is the same for every delivery of the certificate. Then decide, from the status and claimedAt you read, whether to claim, send, give up or flag.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_332'), 3, 'A similar protocol for a different side effect - charging a course purchase: key = "purchase-charge/ord_17"; mark the order "charging" with chargingAt = now only if it is "created"; when you find it "charging" within the payment provider''s dedupe window, charge again with the same key (the provider answers with the first charge) and mark it "charged"; outside the window, mark it "needs-review" instead of charging again.');
