       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_332'), 'Redelivery 24 h or more after the claim is never resent: needs-review; just under 24 h is deduped', '{"certificates":[{"id":"cert_601","learner":"u_601","email":"learner601@mail.codedev.test","course":"typescript-foundations","status":"pending"},{"id":"cert_602","learner":"u_602","email":"learner602@mail.codedev.test","course":"typescript-foundations","status":"pending"},{"id":"cert_603","learner":"u_603","email":"learner603@mail.codedev.test","course":"typescript-foundations","status":"pending"}],"script":[{"at":0,"deliver":"A","cert":"cert_601","crashAfter":"send"},{"at":100,"deliver":"B","cert":"cert_602","crashAfter":"update"},{"at":200,"deliver":"C","cert":"cert_603","crashAfter":"send"},{"at":86400,"deliver":"D","cert":"cert_601"},{"at":86599,"deliver":"F","cert":"cert_603"},{"at":90100,"deliver":"E","cert":"cert_602"}]}', '{"emailsPerLearner":{"u_601":1,"u_602":0,"u_603":1},"certificates":{"cert_601":"needs-review","cert_602":"needs-review","cert_603":"sent"},"errors":[]}', 3, false, true, 6),
