-- challenge chal_quiz_bjm_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_411', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-4-1' AND is_deleted = false LIMIT 1), 'queue-lag-and-age-quiz', 'Depth, age and wait time on the grading queue', 'Two pieces of evidence from the evening the grading queue looked normal on the depth panel while learners waited minutes for their results.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_411');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_411');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_411'), 'Grading queue dashboard, one row per sample (depth = jobs waiting, completed = jobs finished in the previous minute):

time   depth  completed/min  in_flight  oldest_age
17:40   240        420           8         0m 41s
18:40   238         38           6         6m 12s

Two of the eight grading workers were crash-looping from 18:05; and code runner calls on the other six took about 9 s instead of about 1 s.

Statement: "Depth is the same at both samples, yet a submission that joins the queue at 18:40 waits roughly six minutes, while at 17:40 it waited well under a minute."', 'single_choice'::question_type, 'True. How long a new job waits depends on how many jobs are ahead of it and how fast they leave: about depth / throughput. At 17:40 that is 240 / 420 per minute, about 34 seconds; at 18:40 it is 238 / 38 per minute, about 6.3 minutes, which the oldest_age column confirms (6m 12s). Depth stayed flat because learners submitted less in the evening while workers drained much more slowly. The misconception this tests is that depth measures delay: depth is a count, and the same count can mean 30 seconds or 6 minutes depending on throughput. The age of the oldest waiting job measures the delay directly, which is why it is the number to put on the dashboard and the alert.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_411'), 'The worker records wait time when it takes a job:

worker.on("active", (job) => {
  waitSeconds.observe((Date.now() - job.timestamp) / 1000); // histogram, per queue
});

Grading panel, wait time p95 per minute:
18:48  4.1 s
18:49  3.8 s
18:50  (no data)
18:51  (no data)
18:52  (no data)
18:53  (no data)
18:54  (no data)
18:55  296 s

Deploy log: 18:50:02 all grading workers stopped (bad image), 18:55:10 rollback finished. Submissions kept arriving the whole time.

Statement: "Between 18:50 and 18:54 the wait-time panel shows no slow jobs, so learners who submitted in that period waited no more than a few seconds."', 'single_choice'::question_type, 'False. Wait time is observed only when a worker takes a job. With every worker stopped, nothing was taken, so no samples were recorded and the panel shows no data, while every submission from 18:50 was waiting and getting older. The 296 s p95 at 18:55 is those jobs finally being taken after the rollback. A metric recorded at dequeue only describes jobs that have already left the queue: it is blind exactly when the queue is stuck. The misconception is reading "no data" or a low wait-time percentile as "healthy". Sample the age of the oldest waiting job on a timer (a gauge, or the broker''s own metric such as SQS ApproximateAgeOfOldestMessage) so a stuck queue shows a line that climbs one minute per minute.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_bjm_412 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_bjm_412', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-4-1' AND is_deleted = false LIMIT 1), 'queue-lag-report', 'Queue lag report from the worker event log', 'The CodeDev grading, email and certificate workers write one log line per job event, and the on-call team wants a per-minute lag report built from that log instead of a depth chart. Write queueLag(sloSeconds, lines), and the helpers parseLine and nearestRank, in main.ts.

Input (stdin, JSON): { "sloSeconds": number, "lines": string[] }. Each line is "<timestamp> <type> <queue> <jobId>", fields separated by whitespace (leading, trailing and repeated spaces are allowed). The timestamp is UTC with whole seconds, exactly YYYY-MM-DDTHH:MM:SSZ, and must be a real date and time (2026-02-30T09:00:00Z is not). The type is enqueue, dequeue or complete. Every other line - wrong number of fields, unknown type, bad timestamp, empty - is skipped and counted in skippedLines.

Jobs: a job is identified by queue + jobId. Lines can be out of order and can repeat (log shipping duplicates, a redelivered job dequeued twice): for each job keep the earliest enqueue, the earliest dequeue and the earliest complete. A job with no enqueue line was enqueued before the log starts: ignore it entirely.

Windows: one window per queue per UTC minute, for every queue named in a well-formed line and every minute from the minute of the earliest well-formed line to the minute of the latest one (all queues share this range). For the window [start, end), end = start + 60 s:
- depth: jobs waiting at end - enqueued before end, with no dequeue before end and no complete before end (a job that is being processed is not waiting; a job with a complete line but a lost dequeue line is not waiting after its complete);
- oldestAgeSec: the largest end - enqueue among those jobs, in seconds; 0 when depth is 0;
- waitP50Sec, waitP95Sec: percentiles of dequeue - enqueue for jobs whose dequeue is in [start, end); null when there are none;
- processingP95Sec: p95 of complete - dequeue for jobs whose complete is in [start, end) and that have a dequeue; null when there are none;
- breach: oldestAgeSec > sloSeconds.
Percentiles use the nearest-rank method: sort the n values ascending and take the value at 1-based rank ceil(p / 100 * n). For 20 values, p50 is the 10th and p95 the 19th.

Output (stdout, printed by the runner): { "skippedLines": number, "windows": [{ "queue", "minute": "YYYY-MM-DDTHH:MM", "depth", "oldestAgeSec", "waitP50Sec", "waitP95Sec", "processingP95Sec", "breach" }] }, sorted by queue name (plain string comparison) and then by minute. With no well-formed line, windows is []. Logs have at most a few thousand lines; standard library only.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_412');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_412'), 1, 'For each metric, which one timestamp of a job do you need, and in which window does it count? If you first collapse every job to one record, does the order of the lines in the file still matter?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_412'), 2, 'Look at three places: building one record per queue + jobId (keep the smallest timestamp of each type, and skip jobs without an enqueue at the end), the waiting test at the end of a window (a dequeue or a complete before end means the job is no longer waiting), and the rank of a percentile (ceil(p / 100 * n), counted from 1).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_bjm_412'), 3, 'A similar case on the emails queue: job a enqueued 10:00:10, dequeued 10:00:40, completed 10:01:05; job b enqueued 10:00:30 and never dequeued. Window 10:00: a is in flight, so depth is 1 (b) and the oldest age is 10:01:00 - 10:00:30 = 30 s; a''s wait of 30 s gives p50 = p95 = 30. Window 10:01: depth 1, oldest age 90 s, no waits (null), a''s processing time of 25 s gives p95 = 25. For the waits [9, 1, 8, 3]: sorted [1, 3, 8, 9], p50 is rank ceil(2) = 2 -> 3 and p95 is rank ceil(3.8) = 4 -> 9.');
