-- challenge chal_quiz_bjm_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_421', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-4-2' AND is_deleted = false LIMIT 1), 'scaling-workers-quiz', 'Concurrency, downstream limits and the right scaling signal', 'Three pieces of evidence from the afternoon a bulk regrade filled the grading queue: a scaling change, a capacity calculation and an autoscaler that never moved.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421'), 'Grading setup during the regrade:

grading worker   concurrency 1 per replica, replicas 8
grading job      processing time about 3.0 s, almost all of it waiting for the code runner
code runner      at most 16 concurrent executions; a request beyond that gets 429 Too Many Requests

Change deployed at 14:20: replicas 8 -> 40

Statement: "After the change the grading workers will finish about 800 jobs per minute (40 workers x 20 jobs per minute each)."', 'single_choice'::question_type, 'False. Throughput is set by the narrowest stage, not by the number of workers. The code runner runs at most 16 jobs at once and each takes about 3 s, so the whole system finishes at most 16 / 3 = about 5.3 jobs per second, about 320 per minute, whatever the replica count. With 40 workers, 24 of them at any moment get 429 instead of a result; if those jobs are retried, the extra requests add load to the runner exactly when it is full, and the jobs take longer, not shorter. Before the change, 8 workers finished about 160 per minute, so the useful part of the change was going from 8 to 16 slots. The misconception is that worker throughput scales linearly: it does only until a shared downstream (code runner, database pool, a third-party API) is saturated.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421'), 'Capacity sheet for the grading queue at the evening peak:

arrivals          300 submissions per minute (5 per second)
processing time   2 s per job on average
worker slots      8 (replicas x concurrency)
code runner       24 concurrent executions available

Statement: "Eight slots cannot keep up at this peak: on average about 10 jobs must be in progress at once, so the queue keeps growing for as long as the peak lasts."', 'single_choice'::question_type, 'True. Little''s Law says that the average number of jobs in progress equals the throughput times the time each job spends in progress: L = lambda x W = 5 per second x 2 s = 10. Eight slots can finish at most 8 / 2 s = 4 jobs per second, so at 5 arrivals per second one job per second is added to the queue, and the oldest age climbs for the whole peak. The code runner (24) is not the limit here, so adding slots up to about 12-13 (some headroom above 10) is the fix. The misconception is that a queue absorbs a peak by itself: a queue only buffers a peak when the workers can finish faster than jobs arrive on average; otherwise it grows until arrivals drop.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
