WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421'), 'Autoscaler and metrics at 14:10, before anyone changed the replica count:

autoscaler (grading workers)   target CPU 60%, min 8, max 16 replicas, current 8
grading workers                CPU 9%, active jobs 8 of 8 slots
grading queue                  oldest age 22 min, depth 11,400
code runner                    7 of 16 executions in use

Statement: "With worker CPU at 9%, the 22-minute oldest age cannot be caused by too few worker slots, so adding replicas would not help."', 'single_choice'::question_type, 'False. A grading worker spends its time waiting for the code runner, which uses almost no CPU, so CPU says nothing about whether the workers are busy. The evidence that matters is the other two lines: every slot is busy (8 of 8) and the downstream has spare capacity (7 of 16 executions), so the workers are the bottleneck and more slots, up to the runner''s limit, would drain the queue faster. The autoscaler never moved because it watched the wrong signal. The misconception is that low CPU means idle workers; for I/O-bound workers, scale on the queue (oldest age, or backlog per worker) and cap the maximum at what the downstream can take.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_421') AND order_index = 3)
    RETURNING id
)
