-- challenge chal_quiz_bjm_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_bjm_431', (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'background-jobs-messaging') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-bjm-4-3' AND is_deleted = false LIMIT 1), 'operating-queues-quiz', 'Alerts, shutdowns and payload versions on the certificates queue', 'Three pieces of evidence from one week of the certificates queue: an alert history, a worker killed during a deploy and a release that changed the job payload.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_431'), 'Alert history, last 30 days:

GradingQueueBacklog  queue_depth{queue="grading"} > 1000 for 5m
  fired 23 times, all between 18:00 and 21:00, all resolved by themselves within 20 min
  oldest age of the grading queue while it fired: 35 s to 70 s

Email queue, 2026-10-22 01:10 to 04:20 (SMTP credentials expired):
  depth 30, oldest age rising to 3 h 10 min, no alert fired

Proposed rule, per queue:
  queue_oldest_age_seconds > 600 for 5m

Statement: "The proposed rule would have paged for the email stall and would have stayed quiet during all 23 evening peaks."', 'single_choice'::question_type, 'True. During the peaks the oldest grading job was at most 70 s old, far below 600 s, so the age rule does not fire even though depth passed 1,000: those were busy evenings in which jobs still left the queue quickly. The email stall kept a small depth of 30, but its oldest message passed 600 s about ten minutes into the stall and stayed above it for hours, so the age rule pages within about 15 minutes (600 s plus the 5-minute for clause). The misconception is that a bigger depth means a worse incident: depth fires on harmless peaks and misses small stuck queues; age measures the delay users actually suffer. In practice you would also give each queue its own threshold, since 600 s is generous for grading and strict for a nightly export.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_bjm_431') AND order_index = 1)
    RETURNING id
)
